/* === DEPI-SPECIALIZED DETERMINISTIC ENTITY RESOLVER & ARABIC NORMALIZER === */
const input = $input.first()?.json || {};
const rawMsg = input.customer_message || input.sanitized_message || '';

// Conservative Arabic Normalization
let normalized = rawMsg
  .replace(/[\u064B-\u065F\u0670]/g, '') // Tashkeel
  .replace(/\u0640/g, '')               // Tatweel
  .replace(/[إأآٱ]/g, 'ا')              // Alef variants
  .replace(/ى/g, 'ي')                   // Alef Maqsura
  .replace(/\s+/g, ' ')
  .trim();

const msgLower = normalized.toLowerCase();
const isAr = /[\u0600-\u06FF]/.test(rawMsg);
const locale = input.locale || (isAr ? 'ar' : 'en');
const history = Array.isArray(input.conversation_history) ? input.conversation_history : [];
const previousCustomerQuestions = history
  .filter(turn => turn && (turn.sender_type === 'customer' || turn.role === 'user') && typeof turn.content === 'string')
  .slice(-3)
  .map(turn => turn.content.replace(/\s+/g, ' ').trim())
  .filter(Boolean);
const followupPattern = /^(?:و|طب|طيب|تمام|هل ده|هل هذا|وده|وهل|وكمان|وماذا|ماذا عن|what about|and what|does that|is that|it|that)/i;
const isContextualFollowup = rawMsg.trim().length <= 120 && (followupPattern.test(rawMsg.trim()) || /\b(ده|دي|هذا|هذه|ذلك|هو|هي|it|that|those|they)\b/i.test(rawMsg) || /^(?:هل|وهل|ما هو|ما هي|ماذا|is|does|can)\s/i.test(rawMsg.trim()));
const contextualizedQuery = isContextualFollowup && previousCustomerQuestions.length
  ? [...previousCustomerQuestions.slice(-1), rawMsg].join(' ')
  : rawMsg;

// Check conversation history for prior DEPI context
let programResolvedFromHistory = false;
for (const h of history) {
  const c = (h.content || '').toLowerCase();
  if (c.includes('depi') || c.includes('debi') || c.includes('رواد مصر') || c.includes('بناة مصر')) {
    programResolvedFromHistory = true;
    break;
  }
}

// Digilians entity detection (Out-of-scope in DEPI-only release)
const digiliansEntities = [
  'الرواد الرقميون', 'رواد رقميون', 'مبادرة الرواد الرقميون', 'برنامج الرواد الرقميون',
  'digital pioneers initiative', 'digilians'
];
const isDigiliansQuery = digiliansEntities.some(ent => msgLower.includes(ent));

// Comparison phrases
const comparisonPhrases = [
  'الفرق بين', 'مقارنة بين', 'مقارنه بين', 'ايه الفرق', 'ما الفرق',
  'difference between', 'compare', 'comparison', 'versus', 'vs'
];
const isComparisonQuery = comparisonPhrases.some(phrase => msgLower.includes(phrase));

// Explicit DEBI entities (Digital Egypt Builders Initiative - Master's degree scholarship)
const debiSpecificEntities = [
  'بناة مصر الرقمية', 'مبادرة بناة مصر', 'منحة بناة مصر', 'منحة بناة مصر الرقمية',
  'digital egypt builders initiative', 'debi', 'ماجستير بناة مصر'
];
const hasExplicitDebi = debiSpecificEntities.some(ent => msgLower.includes(ent)) || 
  ((msgLower.includes('ماجستير') || msgLower.includes('master')) && !msgLower.includes('depi') && !msgLower.includes('رواد مصر'));

// Explicit DEPI entities (Digital Egypt Pioneers Initiative)
const depiSpecificEntities = [
  'رواد مصر الرقمية', 'مبادرة رواد مصر', 'منحة رواد مصر', 'منحة رواد مصر الرقمية',
  'digital egypt pioneers initiative', 'depi'
];
const hasExplicitDepi = depiSpecificEntities.some(ent => msgLower.includes(ent));

let programScope = 'DEPI';
let isAmbiguous = false;
let isOutOfScope = false;

if (hasExplicitDebi && !hasExplicitDepi) {
  programScope = 'DEBI';
  isOutOfScope = true;
} else if (isDigiliansQuery && !hasExplicitDepi) {
  programScope = 'DIGILIANS';
  isOutOfScope = true;
} else if (isComparisonQuery) {
  programScope = 'COMPARISON';
  isOutOfScope = true;
} else {
  programScope = 'DEPI';
}

// Topic routing
let topicCategory = '';
const isConditions = ['شروط', 'شرط', 'اهلية', 'أهلية', 'التقديم', 'قبول', 'التقدير', 'معدل', 'السن', 'عمر', 'المؤهلة', 'مؤهلة', 'المطلوب', 'مطلوب', 'مستوى', 'gpa', 'grade', 'age', 'required', 'requirements', 'requirement', 'eligibility', 'eligible', 'apply', 'admission', 'who can', 'من يستطيع', 'لغير خريجي'].some(term => msgLower.includes(term));
const isBenefits = ['منحة', 'المنحة', 'منح', 'المنح', 'benefit', 'benefits', 'grant', 'grants'].some(term => msgLower.includes(term));
const isTracks = ['مسار', 'مسارات', 'تخصص', 'تخصصات', 'specialization', 'specializations', 'tracks', 'track', 'data'].some(term => msgLower.includes(term));
const isOnlineTraining = ['أونلاين', 'اونلاين', 'عن بعد', 'online', 'remote'].some(term => msgLower.includes(term));
const isOverview = ['تفاصيل', 'معلومات', 'نبذة', 'نبذه', 'عن المبادرة', 'عن مبادرة', 'ايه هي', 'ما هي', 'ماذا عن', 'فكرة', 'اهداف', 'أهداف', 'overview', 'about', 'details', 'info', 'مبادرة', 'المبادرة'].some(term => msgLower.includes(term));

if (isConditions) topicCategory = 'depi_conditions';
else if (isBenefits) topicCategory = 'debi_benefits';
else if (isTracks) topicCategory = 'debi_tracks';
else if (isOnlineTraining) topicCategory = 'debi_training';
else if (isOverview) topicCategory = 'debi_overview';

if (msgLower.includes('من المؤهل') || msgLower.includes('who is eligible')) topicCategory = '';

// Query-only rewrite: align English-language eligibility queries with the approved FAQ's actual terminology.
const isEnglishEligibility = /(?:انجليزي|انجليزية|اللغة الانجليزي|english|language)/i.test(msgLower);
const retrievalQuery = topicCategory === 'depi_conditions' && isEnglishEligibility
  ? `${contextualizedQuery} شروط الإلتحاق اختبار اللغة الإنجليزية`
  : contextualizedQuery;

// Retrieve only the approved scope that matches this query. General Support is reserved for platform troubleshooting.
const isGeneralSupportQuery = /safe exam browser|\bseb\b|technical support|troubleshoot|browser|install|login|log in|المتصفح|الدعم الفني|مشكلة فنية|تسجيل الدخول/i.test(msgLower);
const programFilter = isOutOfScope
  ? "FALSE"
  : isGeneralSupportQuery
    ? "program = 'COMMON' AND retrieval_scope = 'GENERAL_SUPPORT'"
    : "program = 'DEPI' AND retrieval_scope = 'DEPI_AUTHORITATIVE' AND category NOT IN ('disambiguation', 'comparison')";

let outOfScopeReply = '';
if (programScope === 'DEBI') {
  outOfScopeReply = locale === 'ar'
    ? 'عذراً، يختص هذا المساعد حصرياً بالمعلومات والخدمات الرسمية لمبادرة رواد مصر الرقمية (DEPI)، ولا يقدم معلومات حول منحة بناة مصر الرقمية (DEBI) لدرجة الماجستير.'
    : 'Sorry, this assistant is specialized exclusively in the Digital Egypt Pioneers Initiative (DEPI) and does not cover the Digital Egypt Builders Initiative (DEBI) Master\'s scholarship.';
} else {
  outOfScopeReply = locale === 'ar'
    ? 'عذراً، يختص هذا المساعد حصرياً بمبادرة رواد مصر الرقمية (DEPI) فقط، ولا يقدم معلومات حول مبادرات أخرى مثل مبادرة الرواد الرقميون (Digilians). للاستفسار عن DEPI يسعدنا مساعدتك.'
    : 'Sorry, this assistant is specialized exclusively in the Digital Egypt Pioneers Initiative (DEPI) and does not provide information about other initiatives such as Digilians.';
}

return [{
  json: {
    ...input,
    customer_message: rawMsg,
    normalized_message: normalized,
    contextualized_query: contextualizedQuery,
    retrieval_query: retrievalQuery,
    conversation_history: history.slice(-6),
    locale: locale,
    program_scope: programScope,
    program_filter: programFilter,
    topic_category: topicCategory,
    retrieval_started_ms: Date.now(),
    is_ambiguous: isAmbiguous,
    is_out_of_scope: isOutOfScope,
    out_of_scope_reply: outOfScopeReply,
    program_resolved_from_history: programResolvedFromHistory
  }
}];

/* === FORMAT RAG KNOWLEDGE RESPONSE & CALIBRATED EVIDENCE GATE (DEPI-ONLY) === */
const inputItems = $input.all().map(item => item.json || {});
const rows = inputItems.flatMap(item => Array.isArray(item) ? item : (Array.isArray(item.results) ? item.results : [item]));
const detectorData = $('Program Detector & Query Normalizer').first()?.json || {};
const locale = detectorData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = detectorData.program_scope || 'DEPI';
const isOutOfScope = Boolean(detectorData.is_out_of_scope);
const topicCategory = detectorData.topic_category || '';
const customerMsg = detectorData.customer_message || '';
const normLower = (detectorData.normalized_message || customerMsg).toLowerCase();

// 1. Out-of-Scope Fast Path (Digilians or Comparisons)
if (isOutOfScope) {
  return [{
    json: {
      status: 'out_of_scope',
      action: 'SAFE_DEFLECTION',
      intent_handled: 'faq_query',
      program_scope: programScope,
      is_ambiguous: false,
      is_out_of_scope: true,
      rag_context: '',
      curated_answer: detectorData.out_of_scope_reply,
      evidence_supported: false,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      retrieval_status: 'out_of_scope_initiative',
      request_id: detectorData.request_id || null,
      execution_id: detectorData.execution_id || null,
      channel: detectorData.channel || 'webchat',
      channel_user_id: detectorData.channel_user_id || null,
      customer: detectorData.customer || null,
      conversation: detectorData.conversation || null,
      ai_output: detectorData.ai_output || {},
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'out_of_scope' }
    }
  }];
}

// 2. Calibrate Retrieved Rows - Strictly DEBI records
const relevant = rows.filter(r => r && (r.relevance_score || 0) > 0 && ((r.program === 'DEPI' && r.retrieval_scope === 'DEPI_AUTHORITATIVE') || (r.program === 'COMMON' && r.retrieval_scope === 'GENERAL_SUPPORT')));
const rawEvidenceQuery = detectorData.contextualized_query || detectorData.normalized_message || customerMsg;
const normalizedEvidenceQuery = rawEvidenceQuery.replace(/[\u064B-\u065F\u0670]/g, '').replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
const evidenceStopWords = new Set(['ما','ماذا','هل','هو','هي','من','في','على','عن','الى','إلى','مع','هذا','هذه','ذلك','التي','الذي','وما','وهل','مبادرة','المبادرة','depi','the','what','which','who','when','where','why','how','is','are','does','did','do','and','for','with','from','about','please']);
const evidenceQueryTerms = [...new Set(normalizedEvidenceQuery.split(/[^\u0600-\u06FFa-z0-9]+/i).map(term => term.startsWith('ل') && /[\u0600-\u06FF]/.test(term) ? term.slice(1) : term).map(term => term.startsWith('ال') ? term.slice(2) : term).filter(term => term.length >= 3 && !evidenceStopWords.has(term)))];
function queryEvidenceOverlap(row) {
  const rawText = `${row.question_ar || ''} ${row.question || ''} ${row.answer_ar || ''} ${row.answer || ''}`;
  const evidenceText = rawText.replace(/[\u064B-\u065F\u0670]/g, '').replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
  return evidenceQueryTerms.filter(term => evidenceText.includes(term));
}


// Hard Negative / Unsupported Claim Gate (NASA, Guaranteed Job, 100% employment claims, guarantee claims)
const hasUnsupportedClaims = /(?:nasa|ناسا|تضمن|guarantee)/i.test(normLower);

if (relevant.length > 0) {
  const sorted = [...relevant].sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0));
  const top = sorted[0];
  const topScore = Number(top.relevance_score || 0);
  const semanticScore = Number(top.semantic_score || 0);
  const lexicalScore = Number(top.lexical_score || 0);

  // Lexical / Category connection verification
  const hasLexicalEvidence = lexicalScore >= 6;
  const hasSemanticEvidence = semanticScore >= 14;
  const hasContentEvidence = Number(top.content_match_count || 0) >= 1 || Number(top.keyword_match_count || 0) >= 1;
  const explicitTopicEvidence = Boolean(topicCategory) && (top.category === topicCategory || (top.category || '').includes(topicCategory));
  const matchedQueryTerms = queryEvidenceOverlap(top);
  const hasQueryEvidence = matchedQueryTerms.length >= 3;

  let confidence = 'none';
  let action = 'SAFE_DEFLECTION';
  let evidenceSupported = false;

  if (!hasUnsupportedClaims && hasQueryEvidence) {
    if (explicitTopicEvidence || (hasLexicalEvidence && topScore >= 18) || (hasContentEvidence && topScore >= 20)) {
      confidence = topScore >= 25 ? 'high' : 'medium';
      action = 'ANSWER';
      evidenceSupported = true;
    } else if (hasSemanticEvidence && (hasLexicalEvidence || hasContentEvidence)) {
      confidence = 'medium';
      action = 'ANSWER';
      evidenceSupported = true;
    }
  }

  // Curate clean internal DEPI context
  const context = sorted.slice(0, 3).map(kb => {
    const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
    const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
    const attribution = kb.source_attribution || 'Source attribution unavailable';
    const url = kb.source_url ? `\nSource URL: ${kb.source_url}` : '';
    return `[${kb.program}|${kb.retrieval_scope}] Source: ${attribution}${url}\nسؤال: ${q}\nإجابة: ${a}`;
  }).join('\n---\n');

  const defaultSource = 'مبادرة رواد مصر الرقمية (DEPI)';
  const topCuratedAnswer = isAr ? (top.answer_ar || top.answer) : (top.answer || top.answer_ar);

  return [{
    json: {
      status: action === 'ANSWER' ? 'rag_context_found' : 'low_evidence',
      action: action,
      intent_handled: 'faq_query',
      program_scope: 'DEPI',
      is_ambiguous: false,
      evidence_supported: evidenceSupported,
      rag_context: action === 'ANSWER' ? context : '',
      curated_answer: action === 'ANSWER' ? topCuratedAnswer : '',
      faq_exact_match: topScore >= 18,
      official_source: true,
      customer_message: customerMsg,
      locale: locale,
      top_category: top.category || 'general',
      relevance_score: topScore,
      confidence: confidence,
      confidence_label: confidence.toUpperCase(),
      retrieval_status: action === 'ANSWER' ? 'context_found' : 'low_evidence',
      matched_entries: sorted.length,
      matched_query_terms: matchedQueryTerms,
      top_program: 'DEPI',
      source_attribution: top.source_attribution || defaultSource,
      retrieval_scope: top.retrieval_scope,
      source_url: top.source_url || 'https://depi.gov.eg',
      validation: { status: 'passed' }
    }
  }];
} else {
  return [{
    json: {
      status: 'no_context',
      action: 'SAFE_DEFLECTION',
      intent_handled: 'faq_query',
      program_scope: 'DEPI',
      is_ambiguous: false,
      evidence_supported: false,
      rag_context: '',
      curated_answer: '',
      faq_exact_match: false,
      official_source: false,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      request_id: detectorData.request_id || null,
      execution_id: detectorData.execution_id || null,
      channel: detectorData.channel || 'webchat',
      channel_user_id: detectorData.channel_user_id || null,
      customer: detectorData.customer || null,
      conversation: detectorData.conversation || null,
      pii_detected: detectorData.pii_detected || false,
      ai_output: detectorData.ai_output || {},
      retrieval_status: 'no_context',
      matched_entries: 0,
      source_attribution: 'مبادرة رواد مصر الرقمية (DEPI)',
      validation: { status: 'no_context', reason: 'no_relevant_kb_entry' }
    }
  }];
}

